import{_ as p,a0 as l,w as o,s as d,ao as r,I as i,x as n,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用 Linux 的 ping 命令诊断网络连接问题 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 的 ping 命令诊断网络连接问题 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 的 ping 命令诊断网络连接问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 的 ping 命令诊断网络连接问题 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20211020 Diagnose connectivity issues with the Linux ping command","title":"使用 Linux 的 ping 命令诊断网络连接问题","tag":"202211","desc":""},"relativePath":"202211/20211020 Diagnose connectivity issues with the Linux ping command.md","filePath":"[post].md"}'),g={name:"202211/20211020 Diagnose connectivity issues with the Linux ping command.md"};function c(h,s,u,b,m,k){const e=l("Link");return o(),d("div",null,[s[33]||(s[33]=r(`<h1 id="使用-linux-的-ping-命令诊断网络连接问题" tabindex="-1">使用 Linux 的 ping 命令诊断网络连接问题 <a class="header-anchor" href="#使用-linux-的-ping-命令诊断网络连接问题" aria-label="Permalink to “使用 Linux 的 ping 命令诊断网络连接问题”">​</a></h1><blockquote><p>在本文中，我们将讨论网络连接最基本的诊断工具之一：<code>ping</code> 命令。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202211/20/094045mhhkqhepke4qebks.jpg" alt=""></p><p>如今，联网计算机变得十分普遍，以至于我们大多数人都理所当然地认为，房间一侧的计算机可以连接上房间另一侧的计算机，更不用说能连接上世界的另一端的计算机了。如此，网络使互联网、云、文件共享、媒体流、远程管理、打印等服务成为可能。但是当网络出现问题时，有时很难诊断到底是其中哪一环节出现了问题。下面，我们就来介绍：网络连接最基本的诊断工具之一—— <code>ping</code> 命令。</p><h3 id="基本的-ping-命令" tabindex="-1">基本的 ping 命令 <a class="header-anchor" href="#基本的-ping-命令" aria-label="Permalink to “基本的 ping 命令”">​</a></h3><p>当你无法访问本地网络上的计算机或互联网上的服务器时，你可以 <code>ping</code> 它的 IP 地址。<code>ping</code> 将 <ruby>互联网控制报文协议<rt> Internet Control Message Protocol </rt></ruby>（ICMP）数据包发送到目标 IP 地址。当我们要对网路连接状况进行判断时，ICMP 是个非常有用的协议，本质上 ICMP 是一个响应和应答信号。</p><p>让我们由近及远地进行故障排除。请先 <code>ping</code> 你自己的计算机，以确保你的计算机正在运行 <ruby>网络栈<rt> networking stack </rt></ruby>。你正在操作的计算机称为 <ruby> 主机 <rt> localhost </rt></ruby>，本地回环地址是：<code>127.0.0.1</code>。</p><p><code>ping</code> 命令能用主机的 <ruby>主机名<rt> hostname </rt></ruby>、IP 地址（即 <code>127.0.0.1</code>）或者仅仅用简写 <code>0</code> 来表示 “主机”。</p><p>你可以使用 <code>-c</code> 选项，来控制发送数据包的 <ruby>次数<rt> count </rt></ruby>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 0 -c 1</span></span>
<span class="line"><span>PING 0 (127.0.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 127.0.0.1: icmp_seq=1 ttl=64 time=0.069 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 0 ping statistics ---</span></span>
<span class="line"><span>1 packets transmitted, 1 received, 0% packet loss, time 0ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.069/0.069/0.069/0.000 ms</span></span></code></pre></div><p>在你确认本地网络栈已启动并运行后，接下来，你可以 <code>ping</code> 你的路由器的 IP 地址。路由器的 IP 地址通常以 <code>192.168</code> 或 <code>10</code> 开头。实际的 IP 地址取决于路由器的配置。</p><p>当你没有指定要发送多少次请求时，你可以用 <code>Ctrl+C</code>，来终止 <code>ping</code> 的运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 192.168.0.1 </span></span>
<span class="line"><span>PING 192.168.0.1 (192.168.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=2 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=3 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=4 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=5 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>^C</span></span></code></pre></div><p>如果你能 <code>ping</code> 通路由器，则表示你的有线或无线连接能正常工作。</p><p>对于你的局域网上的其他主机呢？你可以 <code>ping</code> 各种设备，但是并非所有设备都能保证响应，因为一些设备会丢弃 ICMP 数据包，但许多设备会做出响应。例如，我可以 <code>ping</code> 我的打印机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 192.168.0.4</span></span></code></pre></div><h3 id="ping-路由器以外的其他服务器" tabindex="-1">ping 路由器以外的其他服务器 <a class="header-anchor" href="#ping-路由器以外的其他服务器" aria-label="Permalink to “ping 路由器以外的其他服务器”">​</a></h3><p>在确定你自己的网络内部都能连通以后，你还可以 <code>ping</code> 通到路由器以外的其他服务器。同样地，并非所有服务器都能接收 ICMP 数据包，更不用说响应 ICMP 数据包了。然而，也有一些服务器可以接收并响应 ICMP 数据包，而在互联网中的一个重要服务器是 <ruby>域名服务器<rt> nameserver </rt></ruby>。</p><p>谷歌的 <ruby>域名解析服务器<rt> DNS server </rt></ruby>的 IP 地址很容易记住，而且它会响应 <code>ping</code> 请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 2 8.8.8.8</span></span>
<span class="line"><span>PING 8.8.8.8 (8.8.8.8) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 8.8.8.8: icmp_seq=1 ttl=116 time=53.3 ms</span></span>
<span class="line"><span>64 bytes from 8.8.8.8: icmp_seq=2 ttl=116 time=53.5 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 8.8.8.8 ping statistics ---</span></span>
<span class="line"><span>2 packets transmitted, 2 received, 0% packet loss, time 1000ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 53.304/53.424/53.544/0.120 ms</span></span></code></pre></div><p>当你连不上一个网站时，你可以查询全球 DNS 网络，以找出其主机服务器的地址，然后 <code>ping</code> 该服务器。这至少可以告诉你，网站不通的原因是主机已关闭，或者只是 Web 服务器问题。</p><p>例如，假设你尝试访问 <code>example.com</code>，但是发现失败了。首先，使用 <code>host</code> 命令找到 <code>example.com</code> 的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ host example.com</span></span>
<span class="line"><span>example.com has address 93.184.216.34</span></span>
<span class="line"><span>example.com has IPv6 address 2606:2800:220:1:248:1893:25c8:1946</span></span>
<span class="line"><span>example.com mail is handled by 0</span></span></code></pre></div><p>然后，<code>ping</code> 该网站的的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 93.184.216.34 -c 1</span></span></code></pre></div><h3 id="使用-ipv6" tabindex="-1">使用 IPv6 <a class="header-anchor" href="#使用-ipv6" aria-label="Permalink to “使用 IPv6”">​</a></h3><p><code>ping</code> 不仅可以使用 IPv4，还能使用 IPv6。可以通过指定 <code>-4</code> 或 <code>-6</code> 选项，来只使用 IPv4 或 IPv6。</p><h3 id="设置数据包大小" tabindex="-1">设置数据包大小 <a class="header-anchor" href="#设置数据包大小" aria-label="Permalink to “设置数据包大小”">​</a></h3><p>你可以使用 <code>-s</code> 选项，来更改要发送的 ICMP 数据包的 <ruby>大小<rt> size </rt></ruby>。默认的数据大小为 56 字节，加上 8 字节包头，总共得到 64 字节的 ICMP 数据包。以下的示例将发送的 ICMP 数据包大小修改为 35+8=43 个字节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -s 35 -c 5 8.8.8.8</span></span></code></pre></div><p>你可以使用 <code>-D</code> 选项，使得在终端中的每个 <code>ping</code> 回复之前，先打印出当前的时间戳。该时间戳为 UNIX 时间戳，加上微秒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -D 8.8.8.8 </span></span>
<span class="line"><span>PING 8.8.8.8 (8.8.8.8) 56(84) bytes of data.</span></span>
<span class="line"><span>[1634013430.297468] 64 bytes from 8.8.8.8: icmp_seq=1 ttl=116 time=53.3 ms</span></span>
<span class="line"><span>[1634013431.298738] 64 bytes from 8.8.8.8: icmp_seq=2 ttl=116 time=53.1 ms</span></span></code></pre></div><h3 id="设置时间间隔-长短" tabindex="-1">设置时间间隔/长短 <a class="header-anchor" href="#设置时间间隔-长短" aria-label="Permalink to “设置时间间隔/长短”">​</a></h3><p>你可以使用 <code>-i</code> 选项，来更改两次 <code>ping</code> 请求之间的 <ruby>时间间隔<rt> interval </rt></ruby>。以下的示例将 <code>ping</code> 间隔更改为 2 秒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -i 2</span></span></code></pre></div><p>你也可以使用 <code>-w</code> 选项，来在一段时间后终止 <code>ping</code>，单位为秒。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -w 6</span></span></code></pre></div><h3 id="ping-的变体" tabindex="-1">ping 的变体 <a class="header-anchor" href="#ping-的变体" aria-label="Permalink to “ping 的变体”">​</a></h3>`,38)),i("p",null,[s[2]||(s[2]=i("code",null,"ping",-1)),s[3]||(s[3]=n(" 有很多变体。例如，",-1)),s[4]||(s[4]=i("code",null,"iputils",-1)),s[5]||(s[5]=n(" 包提供了 ",-1)),s[6]||(s[6]=i("code",null,"ping",-1)),s[7]||(s[7]=n(" 命令；",-1)),a(e,{href:"https://opensource.com/article/21/8/what-busybox"},{default:t(()=>[...s[0]||(s[0]=[n("Busybox",-1)])]),_:1}),s[8]||(s[8]=n(" 也有",-1)),s[9]||(s[9]=i("code",null,"ping",-1)),s[10]||(s[10]=n(" 命令；BSD 也有；甚至还有一个图形界面的 ",-1)),s[11]||(s[11]=i("code",null,"ping",-1)),s[12]||(s[12]=n("：",-1)),s[13]||(s[13]=i("code",null,"gping",-1)),s[14]||(s[14]=n("，它可用于 Linux、macOS 和 Windows。你可以在 ",-1)),a(e,{href:"https://github.com/orf/gping"},{default:t(()=>[...s[1]||(s[1]=[n("GitHub",-1)])]),_:1}),s[15]||(s[15]=n(" 上找到更多有关 ",-1)),s[16]||(s[16]=i("code",null,"gping",-1)),s[17]||(s[17]=n(" 的信息。",-1))]),s[34]||(s[34]=i("h3",{id:"一起来学习吧",tabindex:"-1"},[n("一起来学习吧 "),i("a",{class:"header-anchor",href:"#一起来学习吧","aria-label":"Permalink to “一起来学习吧”"},"​")],-1)),s[35]||(s[35]=i("p",null,[i("code",null,"ping"),n(" 命令很简单，但它可以帮你诊断网络连接问题。下次再遇到网络连接问题时，让 "),i("code",null,"ping"),n(" 命令成为你解决问题的第一个工具吧。")],-1)),s[36]||(s[36]=i("hr",null,null,-1)),i("p",null,[s[19]||(s[19]=n("via: ",-1)),a(e,{href:"https://opensource.com/article/21/10/linux-ping-command"},{default:t(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/21/10/linux-ping-command",-1)])]),_:1})]),i("p",null,[s[24]||(s[24]=n("作者：",-1)),a(e,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[20]||(s[20]=[n("Seth Kenlon",-1)])]),_:1}),s[25]||(s[25]=n(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 译者：",-1)),a(e,{href:"https://github.com/chai001125"},{default:t(()=>[...s[22]||(s[22]=[n("chai001125",-1)])]),_:1}),s[27]||(s[27]=n(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[30]||(s[30]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[29]||(s[29]=[n("Linux中国",-1)])]),_:1}),s[32]||(s[32]=n(" 荣誉推出",-1))])])}const C=p(g,[["render",c]]);export{x as __pageData,C as default};
